def hero(category, title, lead, role, nature, evidence):
    return f'''<header class="project-hero"><div class="breadcrumbs"><a href="@ROOT@">Início</a> / {category}</div><h1>{title}</h1><p class="lead">{lead}</p><dl class="project-meta"><div><dt>Participação</dt><dd>{role}</dd></div><div><dt>Natureza</dt><dd>{nature}</dd></div><div><dt>Evidência pública</dt><dd>{evidence}</dd></div></dl></header><!-- CASE -->'''

def section(key, label, title, text):
    return f'<section class="case-section" id="{key}"><p class="eyebrow">{label}</p><h2>{title}</h2>{text}</section>'

def next_project(slug, title):
    return f'<a class="next-project" href="@ROOT@projetos/{slug}/"><span><small>Continue explorando</small><strong>{title}</strong></span><span aria-hidden="true">↗</span></a>'

